/**
 * Test suite for the /users endpoint in app.js
 *
 * Dependencies: jest, supertest
 * Install: npm install --save-dev jest supertest
 * Run:     npm test
 */

const request = require('supertest');
const app = require('./app');

// ---------------------------------------------------------------------------
// Shared test data — mirrors the static fixture returned by the endpoint.
// Update this object whenever the real data source changes so that the schema
// tests remain the authoritative contract.
// ---------------------------------------------------------------------------
const EXPECTED_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ---------------------------------------------------------------------------
// Helper: assert that a single user object matches the expected JSON schema.
// Using a helper keeps individual test assertions short and readable while
// still giving precise failure messages.
// ---------------------------------------------------------------------------
function assertUserSchema(user) {
  // 'id' must be a positive integer
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // 'name' must be a non-empty string
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // 'email' must be a non-empty string that looks like an e-mail address
  expect(typeof user.email).toBe('string');
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  // No unexpected extra keys
  const allowedKeys = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((key) => {
    expect(allowedKeys.has(key)).toBe(true);
  });
}

// ---------------------------------------------------------------------------
// Suite
// ---------------------------------------------------------------------------
describe('GET /users', () => {
  // ── Happy-path tests ──────────────────────────────────────────────────────

  describe('happy path', () => {
    let response;

    // Make one request and reuse it across all happy-path assertions so we
    // avoid redundant network round-trips.
    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    it('returns HTTP 200 OK', () => {
      expect(response.status).toBe(200);
    });

    it('sets Content-Type to application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    it('returns a non-empty array', () => {
      expect(Array.isArray(response.body)).toBe(true);
      expect(response.body.length).toBeGreaterThan(0);
    });

    it('returns exactly the expected number of users', () => {
      expect(response.body).toHaveLength(EXPECTED_USERS.length);
    });

    it('returns the correct user data', () => {
      expect(response.body).toEqual(EXPECTED_USERS);
    });

    it('returns users in the original order (id ascending)', () => {
      const ids = response.body.map((u) => u.id);
      expect(ids).toEqual([...ids].sort((a, b) => a - b));
    });
  });

  // ── Schema / contract tests ───────────────────────────────────────────────

  describe('response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    it('every user object contains exactly the keys: id, name, email', () => {
      users.forEach((user) => {
        expect(Object.keys(user).sort()).toEqual(['email', 'id', 'name']);
      });
    });

    it('every user has a valid id (positive integer)', () => {
      users.forEach((user) => {
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    it('every user has a non-empty name string', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim()).not.toBe('');
      });
    });

    it('every user has a valid email address', () => {
      users.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
      });
    });

    it('all user ids are unique', () => {
      const ids = users.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    it('all user emails are unique', () => {
      const emails = users.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });

    it('each user passes the full schema assertion helper', () => {
      users.forEach((user) => assertUserSchema(user));
    });

    it('the response body is a JSON array, not a wrapped object', () => {
      // Guard against accidental { data: [...] } wrapping
      expect(Array.isArray(users)).toBe(true);
    });
  });

  // ── Individual user assertions ────────────────────────────────────────────

  describe('individual user records', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    it('first user is Alice with the correct id and email', () => {
      expect(users[0]).toMatchObject({
        id: 1,
        name: 'Alice',
        email: 'alice@example.com',
      });
    });

    it('second user is Bob with the correct id and email', () => {
      expect(users[1]).toMatchObject({
        id: 2,
        name: 'Bob',
        email: 'bob@example.com',
      });
    });
  });

  // ── Error-handling tests ──────────────────────────────────────────────────
  //
  // The current implementation has no error branch, so we use jest.spyOn to
  // simulate two realistic failure scenarios:
  //   1. An unhandled exception thrown by a middleware / data layer.
  //   2. The route replying with an explicit 500 status.
  //
  // The tests replace the route handler temporarily, assert the behaviour,
  // and then restore the original handler so subsequent tests are unaffected.

  describe('error handling', () => {
    // ── Scenario 1: middleware throws synchronously ──────────────────────

    it('returns 500 when the route handler throws a synchronous error', async () => {
      // Grab the Express router stack entry for GET /users
      const layer = app._router.stack.find(
        (l) => l.route && l.route.path === '/users'
      );

      // Store the original handler so we can restore it afterward
      const originalHandle = layer.route.stack[0].handle;

      // Replace it with one that throws
      layer.route.stack[0].handle = (_req, _res, next) => {
        next(new Error('Simulated data-layer failure'));
      };

      // Add a temporary error handler so Express converts the error to a 500
      // instead of leaving it unhandled in the test process
      const errorHandler = (err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      };
      app.use(errorHandler);

      const response = await request(app).get('/users');

      expect(response.status).toBe(500);
      expect(response.body).toHaveProperty('error');

      // ── Cleanup ──
      layer.route.stack[0].handle = originalHandle;
      // Remove the temporary error handler from the middleware stack
      app._router.stack = app._router.stack.filter(
        (l) => l.handle !== errorHandler
      );
    });

    // ── Scenario 2: route explicitly responds with 500 ───────────────────

    it('returns 500 with a JSON error body when the handler sends an explicit error response', async () => {
      const layer = app._router.stack.find(
        (l) => l.route && l.route.path === '/users'
      );
      const originalHandle = layer.route.stack[0].handle;

      layer.route.stack[0].handle = (_req, res) => {
        res.status(500).json({ error: 'Internal Server Error' });
      };

      const response = await request(app).get('/users');

      expect(response.status).toBe(500);
      expect(response.headers['content-type']).toMatch(/application\/json/);
      expect(response.body).toEqual({ error: 'Internal Server Error' });

      // ── Cleanup ──
      layer.route.stack[0].handle = originalHandle;
    });

    // ── Scenario 3: verify the original handler is fully restored ────────

    it('original handler is restored and still returns 200 after error simulations', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
    });
  });

  // ── HTTP method tests ─────────────────────────────────────────────────────

  describe('unsupported HTTP methods', () => {
    it('returns 404 for POST /users (route not defined)', async () => {
      const response = await request(app).post('/users').send({ name: 'Eve' });
      expect(response.status).toBe(404);
    });

    it('returns 404 for PUT /users (route not defined)', async () => {
      const response = await request(app).put('/users');
      expect(response.status).toBe(404);
    });

    it('returns 404 for DELETE /users (route not defined)', async () => {
      const response = await request(app).delete('/users');
      expect(response.status).toBe(404);
    });

    it('returns 404 for PATCH /users (route not defined)', async () => {
      const response = await request(app).patch('/users');
      expect(response.status).toBe(404);
    });
  });

  // ── Content negotiation tests ─────────────────────────────────────────────

  describe('content negotiation', () => {
    it('responds with JSON even when the client sends Accept: */*', async () => {
      const response = await request(app)
        .get('/users')
        .set('Accept', '*/*');
      expect(response.status).toBe(200);
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    it('responds with JSON when the client explicitly requests application/json', async () => {
      const response = await request(app)
        .get('/users')
        .set('Accept', 'application/json');
      expect(response.status).toBe(200);
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });
  });
});

