/**
 * app.test.js
 * Unit/integration tests for the /users endpoint in app.js
 *
 * Test strategy
 * ─────────────
 * 1. Happy path      – the endpoint returns HTTP 200 with the correct payload.
 * 2. Error handling  – the app survives edge-cases (bad Accept header, wrong
 *                      HTTP method, unknown routes) and responds with the
 *                      appropriate status code without crashing.
 * 3. Schema          – every item in the response array is validated against
 *                      a strict schema (required fields, correct types, format
 *                      constraints) so that accidental shape regressions are
 *                      caught immediately.
 *
 * Dependencies
 * ────────────
 *   jest       – test runner & assertion library  (npm i -D jest)
 *   supertest  – HTTP assertions against an Express app (npm i -D supertest)
 *
 * Run with:
 *   npm test
 *   npx jest --verbose
 *   npx jest --coverage
 */

const request = require('supertest');
const app     = require('./app');

// ---------------------------------------------------------------------------
// Helpers / schema validator
// ---------------------------------------------------------------------------

/**
 * Validates that a single object matches the User schema:
 *   { id: number (positive integer), name: string (non-empty), email: string (valid address) }
 *
 * Returns an array of human-readable violation messages (empty = valid).
 *
 * Using a hand-rolled validator keeps the test file dependency-free
 * (no ajv, zod, joi needed) while still giving descriptive failure messages.
 *
 * @param {unknown} user
 * @returns {string[]}
 */
function validateUserSchema(user) {
  const errors = [];

  if (user === null || typeof user !== 'object' || Array.isArray(user)) {
    errors.push(`Expected a plain object, got ${Array.isArray(user) ? 'array' : typeof user}`);
    // No point checking fields if the wrapper type is wrong.
    return errors;
  }

  // ── id ──────────────────────────────────────────────────────────────────
  if (!('id' in user)) {
    errors.push('Missing required field: id');
  } else if (typeof user.id !== 'number') {
    errors.push(`id must be a number, got ${typeof user.id}`);
  } else if (!Number.isInteger(user.id)) {
    errors.push(`id must be an integer, got ${user.id}`);
  } else if (user.id <= 0) {
    errors.push(`id must be a positive integer, got ${user.id}`);
  }

  // ── name ────────────────────────────────────────────────────────────────
  if (!('name' in user)) {
    errors.push('Missing required field: name');
  } else if (typeof user.name !== 'string') {
    errors.push(`name must be a string, got ${typeof user.name}`);
  } else if (user.name.trim() === '') {
    errors.push('name must not be empty or whitespace-only');
  }

  // ── email ───────────────────────────────────────────────────────────────
  if (!('email' in user)) {
    errors.push('Missing required field: email');
  } else if (typeof user.email !== 'string') {
    errors.push(`email must be a string, got ${typeof user.email}`);
  } else {
    // RFC-5321 relaxed pattern: local@domain.tld
    const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!EMAIL_RE.test(user.email)) {
      errors.push(`email has invalid format: "${user.email}"`);
    }
  }

  // ── no extra fields ──────────────────────────────────────────────────────
  const ALLOWED_KEYS = new Set(['id', 'name', 'email']);
  const extraKeys = Object.keys(user).filter(k => !ALLOWED_KEYS.has(k));
  if (extraKeys.length > 0) {
    errors.push(`Unexpected field(s) in user object: ${extraKeys.join(', ')}`);
  }

  return errors;
}

// ---------------------------------------------------------------------------
// Test suites
// ---------------------------------------------------------------------------

describe('GET /users', () => {

  // ─────────────────────────────────────────────────────────────────────────
  // 1. Happy path
  // ─────────────────────────────────────────────────────────────────────────
  describe('Happy path', () => {

    it('responds with HTTP 200', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
    });

    it('sets Content-Type to application/json', async () => {
      const res = await request(app).get('/users');
      // supertest's .type() helper is not available here; check the header directly.
      expect(res.headers['content-type']).toMatch(/application\/json/);
    });

    it('returns a non-empty array', async () => {
      const res = await request(app).get('/users');
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThan(0);
    });

    it('returns exactly 2 users (current seed data)', async () => {
      const res = await request(app).get('/users');
      expect(res.body).toHaveLength(2);
    });

    it('contains Alice as the first user', async () => {
      const res = await request(app).get('/users');
      expect(res.body[0]).toMatchObject({
        id:    1,
        name:  'Alice',
        email: 'alice@example.com',
      });
    });

    it('contains Bob as the second user', async () => {
      const res = await request(app).get('/users');
