/**
 * app.test.js
 *
 * Unit tests for the /users endpoint in app.js.
 *
 * Test groups
 * ───────────
 * 1. Happy path          – successful responses with correct data
 * 2. Response schema     – every field is present and correctly typed
 * 3. HTTP contract       – method, headers, status codes
 * 4. Error / edge cases  – 404 on unknown routes, unsupported methods
 */

const request = require('supertest');
const app = require('./app');

// ─── helpers ────────────────────────────────────────────────────────────────

/**
 * Returns true when every key in `schema` matches the value in `obj`
 * using the typeof check supplied.
 *
 *   matchesSchema({ id: 'number', name: 'string' }, { id: 1, name: 'Alice' })
 *   // → true
 */
function matchesSchema(schema, obj) {
  return Object.entries(schema).every(
    ([key, type]) => key in obj && typeof obj[key] === type
  );
}

/** Expected shape of a single user object returned by GET /users */
const USER_SCHEMA = {
  id:    'number',
  name:  'string',
  email: 'string',
};

// ─── test suites ────────────────────────────────────────────────────────────

describe('GET /users', () => {

  // ── 1. Happy path ─────────────────────────────────────────────────────────

  describe('Happy path', () => {
    let response;

    // Execute the request once; share the result across the tests below.
    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    test('responds with HTTP 200', () => {
      expect(response.statusCode).toBe(200);
    });

    test('returns a non-empty array', () => {
      expect(Array.isArray(response.body)).toBe(true);
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('returns exactly the two seeded users', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has the correct id, name, and email', () => {
      expect(response.body[0]).toEqual({
        id:    1,
        name:  'Alice',
        email: 'alice@example.com',
      });
    });

    test('second user has the correct id, name, and email', () => {
      expect(response.body[1]).toEqual({
        id:    2,
        name:  'Bob',
        email: 'bob@example.com',
      });
    });

    test('user ids are unique across the list', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });
  });

  // ── 2. Response-schema validation ─────────────────────────────────────────

  describe('Response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    test('Content-Type header is application/json', async () => {
      const response = await request(app).get('/users');
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('every user object contains all required keys', () => {
      const requiredKeys = Object.keys(USER_SCHEMA);
      users.forEach((user) => {
        requiredKeys.forEach((key) => {
          expect(user).toHaveProperty(key);
        });
      });
    });

    test('every user object matches the expected schema types', () => {
      users.forEach((user) => {
        expect(matchesSchema(USER_SCHEMA, user)).toBe(true);
      });
    });

    test('id field is a positive integer', () => {
      users.forEach((user) => {
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('email field contains the "@" character', () => {
      users.forEach((user) => {
        expect(user.email).toContain('@');
      });
    });

    test('name field is a non-empty string', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('no unexpected extra keys are present on user objects', () => {
      const allowedKeys = new Set(Object.keys(USER_SCHEMA));
      users.forEach((user) => {
        Object.keys(user).forEach((key) => {
          expect(allowedKeys.has(key)).toBe(true);
        });
      });
    });

    test('response body is a JSON array (not a wrapped object)', () => {
      // The raw body must be an array, not { data: [...] } or similar.
      expect(Array.isArray(users)).toBe(true);
    });
  });

  // ── 3. HTTP contract ──────────────────────────────────────────────────────

  describe('HTTP contract', () => {
    test('responds to GET but not POST (405 or 404)', async () => {
      const response = await request(app).post('/users').send({});
      // Express returns 404 for unregistered method+path combos by default.
