/**
 * app.test.js
 *
 * Unit/integration tests for the /users endpoint in app.js.
 * Uses Jest as the test runner and Supertest to fire HTTP requests
 * against the Express app without binding to a real port.
 *
 * Test suites
 * ───────────
 * 1. Happy-path           – normal, successful responses
 * 2. Error-handling       – forced failures, bad routes, wrong methods
 * 3. Response-schema      – structural / type validation of every field
 */

const request = require('supertest');
const app = require('./app');

// ─── helpers ────────────────────────────────────────────────────────────────

/**
 * Validates that a single user object matches the expected schema.
 * Throws via Jest `expect` on the first violation so error messages
 * point at the exact field that is wrong.
 *
 * Expected shape:
 *   { id: <positive integer>, name: <non-empty string>, email: <RFC-5322-ish string> }
 */
function assertUserSchema(user) {
  // id — must be a positive integer
  expect(user).toHaveProperty('id');
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // name — must be a non-empty string
  expect(user).toHaveProperty('name');
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // email — must be a string that looks like an email address
  expect(user).toHaveProperty('email');
  expect(typeof user.email).toBe('string');
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
}

/**
 * Returns a shallow copy of a user object with `extra` properties merged in.
 * Used to verify that the schema validator correctly rejects unexpected shapes.
 */
function userWith(overrides) {
  return { id: 1, name: 'Alice', email: 'alice@example.com', ...overrides };
}

// ─── test suites ────────────────────────────────────────────────────────────

// ---------------------------------------------------------------------------
// Suite 1 — Happy path
// ---------------------------------------------------------------------------
describe('GET /users — happy path', () => {
  let response;

  // Make a single request and reuse the result across tests in this suite
  // to avoid redundant network calls.
  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  test('responds with HTTP 200 OK', () => {
    expect(response.statusCode).toBe(200);
  });

  test('sets Content-Type to application/json', () => {
    expect(response.headers['content-type']).toMatch(/application\/json/);
  });

  test('returns a non-empty array', () => {
    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBeGreaterThan(0);
  });

  test('returns exactly two users', () => {
    expect(response.body).toHaveLength(2);
  });

  test('first user is Alice with correct data', () => {
    const alice = response.body[0];
    expect(alice).toEqual({
      id: 1,
      name: 'Alice',
      email: 'alice@example.com',
    });
  });

  test('second user is Bob with correct data', () => {
    const bob = response.body[1];
    expect(bob).toEqual({
      id: 2,
      name: 'Bob',
      email: 'bob@example.com',
    });
  });

  test('all user IDs are unique', () => {
    const ids = response.body.map((u) => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  test('all user emails are unique', () => {
    const emails = response.body.map((u) => u.email);
    const uniqueEmails = new Set(emails);
    expect(uniqueEmails.size).toBe(emails.length);
  });

  test('response body does not contain sensitive fields', () => {
    response.body.forEach((user) => {
      expect(user).not.toHaveProperty('password');
      expect(user).not.toHaveProperty('passwordHash');
      expect(user).not.toHaveProperty('token');
      expect(user).not.toHaveProperty('secret');
    });
  });
});

// ---------------------------------------------------------------------------
// Suite 2 — Error handling
// ---------------------------------------------------------------------------
describe('GET /users — error handling', () => {
  test('returns 404 for an unknown route', async () => {
    const res = await request(app).get('/users/unknown-sub-path');
    expect(res.statusCode).toBe(404);
  });

  test('returns 404 for a completely different route', async () => {
    const res = await request(app).get('/nonexistent');
    expect(res.statusCode).toBe(404);
  });

  test('POST /users is not a supported method and returns 404', async () => {
    // Express returns 404 when no handler is registered for a method+path.
    const res = await request(app).post('/users');
    expect(res.statusCode).toBe(404);
  });

  test('PUT /users is not a supported method and returns 404', async () => {
    const res = await request(app).put('/users');
    expect(res.statusCode).toBe(404);
  });

  test('DELETE /users is not a supported method and returns 404', async () => {
    const res = await request(app).delete('/users');
    expect(res.statusCode).toBe(404);
  });

  test('PATCH /users is not a supported method and returns 404', async () => {
    const res = await request(app).patch('/users');
    expect(res.statusCode).toBe(404);
  });

  test('returns 404 with a body for an unsupported nested path', async () => {
    const res = await request(app).get('/users/1');
    expect(res.statusCode).toBe(404);
  });

  describe('simulated internal server error', () => {
    /**
     * We temporarily monkey-patch res.json to throw so we can verify that
     * a thrown error inside a route handler results in a 500 response when
     * an error-handling middleware is present.
     *
     * Because app.js does not yet have an error-handling middleware, Express
     * will propagate the error and return its default 500 behaviour in test
     * mode.  The test therefore asserts the status code is NOT 200, covering
     * both the default Express 500 and any custom error handler.
     */
    let originalJson;

    beforeEach(() => {
      // Save a reference to the original prototype method
      const http = require('http');
      const ServerResponse = http.ServerResponse;
      originalJson = ServerResponse.prototype.json;
    });

    afterEach(() => {
      // Always restore to avoid polluting other tests
      if (originalJson) {
        const http = require('http');
        http.ServerResponse.prototype.json = originalJson;
      }
    });

    test('GET /users with a forced route error does not return 200', async () => {
      // Replace the express app's route temporarily by registering a
      // one-shot middleware that throws before the real handler fires.
      const express = require('express');
      const faultyApp = express();

      faultyApp.get('/users', (_req, _res, next) => {
        next(new Error('Simulated database failure'));
      });

      // Add a minimal error handler so supertest gets a proper response
      // instead of the process crashing.
      // eslint-disable-next-line no-unused-vars
      faultyApp.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const res = await request(faultyApp).get('/users');
      expect(res.statusCode).toBe(500);
      expect(res.body).toHaveProperty('error', 'Simulated database failure');
    });

    test('error response body contains an "error" key', async () => {
      const express = require('express');
      const faultyApp = express();

      faultyApp.get('/users', (_req, _res, next) => {
        next(new Error('Something went wrong'));
      });

      faultyApp.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const res = await request(faultyApp).get('/users');
      expect(res.body).toHaveProperty('error');
      expect(typeof res.body.error).toBe('string');
    });
  });
});

// ---------------------------------------------------------------------------
// Suite 3 — Response schema validation
// ---------------------------------------------------------------------------
describe('GET /users — response schema', () => {
  let users;

  beforeAll(async () => {
    const res = await request(app).get('/users');
    users = res.body;
  });

  // ── Top-level shape ──────────────────────────────────────────────────────

  test('response body is an Array (not an object wrapper)', () => {
    expect(Array.isArray(users)).toBe(true);
  });

  test('response body is not null or undefined', () => {
    expect(users).not.toBeNull();
    expect(users).not.toBeUndefined();
  });

  // ── Per-user field presence ──────────────────────────────────────────────

  test('every user has exactly the fields: id, name, email', () => {
    users.forEach((user) => {
      const keys = Object.keys(user).sort();
      expect(keys).toEqual(['email', 'id', 'name']); // sorted alphabetically
    });
  });

  // ── id field ────────────────────────────────────────────────────────────

  test('every user.id is a number', () => {
    users.forEach((user) => {
      expect(typeof user.id).toBe('number');
    });
  });

  test('every user.id is a positive integer', () => {
    users.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('every user.id is finite', () => {
    users.forEach((user) => {
      expect(Number.isFinite(user.id)).toBe(true);
    });
  });

  // ── name field ───────────────────────────────────────────────────────────

  test('every user.name is a string', () => {
    users.forEach((user) => {
      expect(typeof user.name).toBe('string');
    });
  });

  test('every user.name is non-empty after trimming', () => {
    users.forEach((user) => {
      expect(user.name.trim().length).toBeGreaterThan(0);
    });
  });

  test('every user.name contains only printable characters', () => {
    users.forEach((user) => {
      // Disallows raw control characters (e.g. \0, \n) inside names
      expect(user.name).toMatch(/^[\x20-\x7E\u00A0-\uFFFF]+$/);
    });
  });

  // ── email field ──────────────────────────────────────────────────────────

  test('every user.email is a string', () => {
    users.forEach((user) => {
      expect(typeof user.email).toBe('string');
    });
  });

  test('every user.email matches a basic email pattern', () => {
    users.forEach((user) => {
      expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
    });
  });

  test('every user.email contains exactly one "@" symbol', () => {
    users.forEach((user) => {
      const atCount = (user.email.match(/@/g) || []).length;
      expect(atCount).toBe(1);
    });
  });

  test('every user.email does not contain whitespace', () => {
    users.forEach((user) => {
      expect(user.email).not.toMatch(/\s/);
    });
  });

  test('every user.email local-part is non-empty', () => {
    users.forEach((user) => {
      const localPart = user.email.split('@')[0];
      expect(localPart.length).toBeGreaterThan(0);
    });
  });

  test('every user.email domain-part contains a dot', () => {
    users.forEach((user) => {
      const domain = user.email.split('@')[1];
      expect(domain).toContain('.');
    });
  });

  // ── Composite schema assertion using the helper ──────────────────────────

  test('every user fully satisfies the complete user schema', () => {
    users.forEach(assertUserSchema);
  });

  // ── Negative schema tests (assertUserSchema rejects bad shapes) ──────────

  describe('schema helper correctly rejects invalid user objects', () => {
    test('rejects a user with a string id', () => {
      expect(() => assertUserSchema(userWith({ id: 'abc' }))).toThrow();
    });

    test('rejects a user with a zero id', () => {
      expect(() => assertUserSchema(userWith({ id: 0 }))).toThrow();
    });

    test('rejects a user with a negative id', () => {
      expect(() => assertUserSchema(userWith({ id: -1 }))).toThrow();
    });

    test('rejects a user with a float id', () => {
      expect(() => assertUserSchema(userWith({ id: 1.5 }))).toThrow();
    });

    test('rejects a user with an empty name', () => {
      expect(() => assertUserSchema(userWith({ name: '' }))).toThrow();
    });

    test('rejects a user with a whitespace-only name', () => {
      expect(() => assertUserSchema(userWith({ name: '   ' }))).toThrow();
    });

    test('rejects a user with a numeric name', () => {
      expect(() => assertUserSchema(userWith({ name: 42 }))).toThrow();
    });

    test('rejects a user with an email missing "@"', () => {
      expect(() => assertUserSchema(userWith({ email: 'notanemail' }))).toThrow();
    });

    test('rejects a user with an email missing domain', () => {
      expect(() => assertUserSchema(userWith({ email: 'user@' }))).toThrow();
    });

