/**
 * Test suite for app.js — /users endpoint
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *
 * Run:
 *   npm test
 */

const request = require('supertest');
const app = require('./app');

// ---------------------------------------------------------------------------
// Schema validator helper
// Checks that a single user object matches the expected shape and types.
// ---------------------------------------------------------------------------
function isValidUser(user) {
  return (
    typeof user === 'object' &&
    user !== null &&
    typeof user.id === 'number' &&
    Number.isInteger(user.id) &&
    user.id > 0 &&
    typeof user.name === 'string' &&
    user.name.trim().length > 0 &&
    typeof user.email === 'string' &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email) // basic e-mail pattern
  );
}

// ---------------------------------------------------------------------------
// Shared server lifecycle
// ---------------------------------------------------------------------------
let server;

beforeAll((done) => {
  // Start the server on an ephemeral port so tests never conflict with the
  // production port (3000) or with each other when run in parallel.
  server = app.listen(0, done);
});

afterAll((done) => {
  server.close(done);
});

// ===========================================================================
// GET /users
// ===========================================================================
describe('GET /users', () => {
  // -------------------------------------------------------------------------
  // Happy-path tests
  // -------------------------------------------------------------------------
  describe('happy path', () => {
    let response;

    beforeAll(async () => {
      response = await request(server).get('/users');
    });

    test('responds with HTTP 200 OK', () => {
      expect(response.status).toBe(200);
    });

    test('responds with Content-Type application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('response body is an array', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('returns at least one user', () => {
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('returns the expected number of seeded users (2)', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has the correct seeded data', () => {
      expect(response.body[0]).toEqual({
        id: 1,
        name: 'Alice',
        email: 'alice@example.com',
      });
    });

    test('second user has the correct seeded data', () => {
      expect(response.body[1]).toEqual({
        id: 2,
        name: 'Bob',
        email: 'bob@example.com',
      });
    });

    test('user ids are unique', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });
  });

  // -------------------------------------------------------------------------
  // Schema / response-format tests
  // -------------------------------------------------------------------------
  describe('response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(server).get('/users');
      users = response.body;
    });

    test('every user has exactly the expected keys: id, name, email', () => {
      const EXPECTED_KEYS = ['id', 'name', 'email'];
      users.forEach((user, index) => {
        const keys = Object.keys(user).sort();
        expect(keys).toEqual(
          EXPECTED_KEYS.slice().sort(),
          `User at index ${index} has unexpected keys: ${keys}`
        );
      });
    });

    test('every user.id is a positive integer', () => {
      users.forEach((user, index) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('every user.name is a non-empty string', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('every user.email is a valid e-mail address', () => {
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      users.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(EMAIL_RE.test(user.email)).toBe(true);
      });
    });

    test('every user passes the full isValidUser schema check', () => {
      users.forEach((user, index) => {
        expect(isValidUser(user)).toBe(true);
      });
    });

    test('response body does NOT contain unexpected top-level fields (no metadata wrapping)', () => {
      // The contract is a bare array, not { data: [], meta: {} }
      expect(Array.isArray(users)).toBe(true);
    });
  });

  // -------------------------------------------------------------------------
  // Error-handling tests
  // -------------------------------------------------------------------------
  describe('error handling', () => {
    test('returns 404 for a non-existent route', async () => {
      const response = await request(server).get('/users/nonexistent-route');
      expect(response.status).toBe(404);
    });

    test('does not accept a POST request — responds with 404 (no handler defined)', async () => {
      // Express returns 404 when no route matches method + path
      const response = await request(server)
        .post('/users')
        .send({ name: 'Charlie', email: 'charlie@example.com' })
        .set('Content-Type', 'application/json');
      expect(response.status).toBe(404);
    });

    test('does not accept a PUT request — responds with 404', async () => {
      const response = await request(server).put('/users');
      expect(response.status).toBe(404);
    });

    test('does not accept a DELETE request — responds with 404', async () => {
      const response = await request(server).delete('/users');
      expect(response.status).toBe(404);
    });

    test('does not accept a PATCH request — responds with 404', async () => {
      const response = await request(server).patch('/users');
      expect(response.status).toBe(404);
    });

    test('ignores unexpected query parameters and still returns 200', async () => {
      const response = await request(server).get('/users?foo=bar&page=999');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('ignores unexpected request headers and still returns 200', async () => {
      const response = await request(server)
        .get('/users')
        .set('X-Custom-Header', 'unexpected-value');
      expect(response.status).toBe(200);
    });
  });

  // -------------------------------------------------------------------------
  // Sanity / regression tests
  // -------------------------------------------------------------------------
  describe('regression / sanity checks', () => {
    test('is idempotent — two sequential calls return identical data', async () => {
      const first = await request(server).get('/users');
      const second = await request(server).get('/users');
      expect(second.body).toEqual(first.body);
    });

    test('response body is valid JSON (supertest parses it without error)', async () => {
      const response = await request(server).get('/users');
      // If body were unparseable, supertest would leave it as a string
      expect(typeof response.body).not.toBe('string');
    });

    test('/health endpoint is unaffected and still returns ok', async () => {
      const response = await request(server).get('/health');
      expect(response.status).toBe(200);
      expect(response.body.status).toBe('ok');
    });
  });
});

