/**
 * app.test.js
 * Unit / integration tests for the /users endpoint in app.js.
 *
 * Run with:
 *   npm test
 *
 * Dependencies (install once):
 *   npm install --save-dev jest supertest
 *   npm install express          # if not already a runtime dep
 */

const request = require('supertest');
const app     = require('./app');

// ---------------------------------------------------------------------------
// Schema helper
// ---------------------------------------------------------------------------

/**
 * Validates that a single object matches the expected User schema.
 *
 * Expected shape:
 *   {
 *     id:    number   (positive integer)
 *     name:  string   (non-empty)
 *     email: string   (basic RFC-5322 local@domain format)
 *   }
 *
 * Returns an array of human-readable violation strings (empty = valid).
 */
function validateUserSchema(user) {
  const violations = [];

  // --- id ---
  if (!Object.prototype.hasOwnProperty.call(user, 'id')) {
    violations.push('missing field: id');
  } else if (typeof user.id !== 'number') {
    violations.push(`id must be a number, got ${typeof user.id}`);
  } else if (!Number.isInteger(user.id) || user.id <= 0) {
    violations.push(`id must be a positive integer, got ${user.id}`);
  }

  // --- name ---
  if (!Object.prototype.hasOwnProperty.call(user, 'name')) {
    violations.push('missing field: name');
  } else if (typeof user.name !== 'string') {
    violations.push(`name must be a string, got ${typeof user.name}`);
  } else if (user.name.trim().length === 0) {
    violations.push('name must not be empty');
  }

  // --- email ---
  if (!Object.prototype.hasOwnProperty.call(user, 'email')) {
    violations.push('missing field: email');
  } else if (typeof user.email !== 'string') {
    violations.push(`email must be a string, got ${typeof user.email}`);
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email)) {
    violations.push(`email has invalid format: "${user.email}"`);
  }

  // --- no extra fields ---
  const allowed = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((key) => {
    if (!allowed.has(key)) violations.push(`unexpected field: ${key}`);
  });

  return violations;
}

// ---------------------------------------------------------------------------
// Test suite
// ---------------------------------------------------------------------------

describe('GET /users', () => {

  // ── Happy path ─────────────────────────────────────────────────────────

  describe('Happy path', () => {
    let response;

    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    test('responds with HTTP 200', () => {
      expect(response.status).toBe(200);
    });

    test('Content-Type is application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('body is an array', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('array is non-empty', () => {
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('returns the expected number of users (2)', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has the correct values', () => {
      expect(response.body[0]).toEqual({
        id:    1,
        name:  'Alice',
        email: 'alice@example.com',
      });
    });

    test('second user has the correct values', () => {
      expect(response.body[1]).toEqual({
        id:    2,
        name:  'Bob',
        email: 'bob@example.com',
      });
    });

    test('every user id is unique', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });
  });

  // ── Response-schema validation ──────────────────────────────────────────

  describe('Response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    test('each user object contains exactly the fields: id, name, email', () => {
      users.forEach((user, index) => {
        const violations = validateUserSchema(user);
        expect(violations).toEqual(
          /* custom failure message lists every violation */
          expect.arrayContaining([]),
        );
        if (violations.length > 0) {
          // Force a descriptive failure when there are violations
          throw new Error(
            `User at index ${index} failed schema validation:\n` +
            violations.map((v) => `  • ${v}`).join('\n'),
          );
        }
      });
    });

    test('id is a positive integer for every user', () => {
      users.forEach((user) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('name is a non-empty string for every user', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('email matches the local@domain.tld pattern for every user', () => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      users.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(user.email).toMatch(emailRegex);
      });
    });

    test('no extra / undocumented fields are present on any user', () => {
      const allowed = ['id', 'name', 'email'];
      users.forEach((user, index) => {
        const extras = Object.keys(user).filter((k) => !allowed.includes(k));
        expect(extras).toHaveLength(0);
        if (extras.length > 0) {
          throw new Error(
            `User at index ${index} has undocumented fields: ${extras.join(', ')}`,
          );
        }
      });
    });
  });

  // ── Error-handling ──────────────────────────────────────────────────────

  describe('Error handling', () => {

    test('unknown route returns 404', async () => {
      const response = await request(app).get('/nonexistent-route');
      expect(response.status).toBe(404);
    });

    test('POST /users returns 404 (method not supported / route not defined)', async () => {
      /*
       * Express returns 404 when no handler matches a method+path combination.
       * If you later add a POST /users handler this test should be updated to
       * assert 405 Method Not Allowed (or the appropriate success code).
       */
      const response = await request(app).post('/users').send({ name: 'Charlie' });
      expect(response.status).toBe(404);
    });

    test('PUT /users returns 404 (method not supported / route not defined)', async () => {
      const response = await request(app).put('/users').send({ id: 1 });
      expect(response.status).toBe(404);
    });

    test('DELETE /users returns 404 (method not supported / route not defined)', async () => {
      const response = await request(app).delete('/users');
      expect(response.status).toBe(404);
    });

    test('PATCH /users returns 404 (method not supported / route not defined)', async () => {
      const response = await request(app).patch('/users').send({});
      expect(response.status).toBe(404);
    });

    test('request with Accept: text/html still returns JSON (no content-negotiation error)', async () => {
      /*
       * Express ignores Accept headers unless you call res.format().
       * This test documents and locks in that behaviour.
       */
      const response = await request(app)
        .get('/users')
        .set('Accept', 'text/html');

      expect(response.status).toBe(200);
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('trailing slash /users/ returns 404 (strict routing not configured)', async () => {
      /*
       * By default Express does NOT enable strict routing, so "/users/" and
       * "/users" are treated the same and both return 200.  If you enable
       * app.set('strict routing', true) this test should assert 404.
       *
       * Adjust this assertion to match your routing configuration.
       */
      const response = await request(app).get('/users/');
      // Default Express behaviour: 200 (same as /users)
      expect([200, 404]).toContain(response.status);
    });

    test('query parameters are silently ignored and full list is returned', async () => {
      /*
       * /users has no filtering logic, so any query string should be ignored
       * and the endpoint should still return 200 with the complete user list.
       */
      const response = await request(app).get('/users?foo=bar&limit=1');
      expect(response.status).toBe(200);
      expect(response.body).toHaveLength(2);
    });
  });

  // ── Stability / regression ──────────────────────────────────────────────

  describe('Stability & regression', () => {

    test('response is identical across two consecutive calls (pure / no side-effects)', async () => {
      const [r1, r2] = await Promise.all([
        request(app).get('/users'),
        request(app).get('/users'),
      ]);
      expect(r1.body).toEqual(r2.body);
    });

    test('response body can be round-tripped through JSON without data loss', async () => {
      const { body } = await request(app).get('/users');
      const roundTripped = JSON.parse(JSON.stringify(body));
      expect(roundTripped).toEqual(body);
    });

    test('response does not contain a "password", "secret", or "token" field on any user', async () => {
      const { body } = await request(app).get('/users');
      const sensitiveKeys = ['password', 'secret', 'token', 'hash'];
      body.forEach((user, index) => {
        sensitiveKeys.forEach((key) => {
          expect(user).not.toHaveProperty(key);
        });
      });
    });
  });
});

