 *  - Happy path          – correct status, body, and headers
 *  - Response schema     – every user object matches the expected shape / types
 *  - Error handling      – 404 for unknown routes, unsupported HTTP methods
 *  - Edge / regression   – empty-list tolerance, no extra fields, idempotency
 */

const request = require('supertest');
const app     = require('./app');

// ─── Schema helper ────────────────────────────────────────────────────────────

/**
 * Validates a single user object against the expected schema.
 *
 * Expected shape:
 *   { id: <positive integer>, name: <non-empty string>, email: <valid email> }
 *
 * Returns an array of human-readable violation strings (empty = valid).
 */
function validateUserSchema(user) {
  const violations = [];

  // id – must be a positive integer
  if (typeof user.id !== 'number')          violations.push(`id must be a number, got ${typeof user.id}`);
  else if (!Number.isInteger(user.id))      violations.push(`id must be an integer, got ${user.id}`);
  else if (user.id <= 0)                    violations.push(`id must be positive, got ${user.id}`);

  // name – must be a non-empty string
  if (typeof user.name !== 'string')        violations.push(`name must be a string, got ${typeof user.name}`);
  else if (user.name.trim().length === 0)   violations.push('name must not be empty');

  // email – must be a string that matches a basic email pattern
  if (typeof user.email !== 'string')       violations.push(`email must be a string, got ${typeof user.email}`);
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email))
                                            violations.push(`email is not valid, got "${user.email}"`);

  // No unexpected extra fields
  const knownKeys    = new Set(['id', 'name', 'email']);
  const unknownKeys  = Object.keys(user).filter(k => !knownKeys.has(k));
  if (unknownKeys.length > 0)
    violations.push(`unexpected fields: ${unknownKeys.join(', ')}`);

  return violations;
}

