      const res = await request(app).put('/users').send({});
      expect(res.statusCode).toBe(404);
    });

    it('DELETE /users is not supported and returns 404', async () => {
      const res = await request(app).delete('/users');
      expect(res.statusCode).toBe(404);
    });

    it('PATCH /users is not supported and returns 404', async () => {
      const res = await request(app).patch('/users').send({});
      expect(res.statusCode).toBe(404);
    });

  });

