/**
 * Test suite for the /users endpoint in app.js
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *   npm install express
 *
 * Run tests:
 *   npm test
 */

const request = require('supertest');
const app = require('./app');

// ---------------------------------------------------------------------------
// Schema validator helper
// Validates that a single user object matches the expected shape and types
// without pulling in a heavy schema library like Joi or Zod.
// ---------------------------------------------------------------------------
function isValidUser(user) {
  return (
    user !== null &&
    typeof user === 'object' &&
    typeof user.id === 'number' &&
    Number.isInteger(user.id) &&
    user.id > 0 &&
    typeof user.name === 'string' &&
    user.name.trim().length > 0 &&
    typeof user.email === 'string' &&
    // Basic RFC-5322-inspired check: local@domain.tld
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email)
  );
}

// ---------------------------------------------------------------------------
// Shared server lifecycle
// supertest can accept an express app directly and binds an ephemeral port
// automatically, so we never collide with the hard-coded port 3000.
// ---------------------------------------------------------------------------
let server;

beforeAll((done) => {
  // Bind on port 0 → OS picks a free ephemeral port.
  server = app.listen(0, done);
});

afterAll((done) => {
  server.close(done);
});

