// GET /users
// ===========================================================================
describe('GET /users', () => {
  // -------------------------------------------------------------------------
  // Happy-path tests
  // -------------------------------------------------------------------------
  describe('Happy path', () => {
    let response;

    // Make one request and reuse it across the happy-path assertions so we
    // don't hammer the server with redundant calls.
    beforeEach(async () => {
      response = await request(server).get('/users');
    });

    test('returns HTTP 200 OK', async () => {
      expect(response.status).toBe(200);
    });

    test('responds with Content-Type application/json', async () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('response body is an array', async () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('returns at least one user', async () => {
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('returns the expected number of seed users (2)', async () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has the correct id', async () => {
      expect(response.body[0].id).toBe(1);
    });

    test('second user has the correct id', async () => {
      expect(response.body[1].id).toBe(2);
    });

    test('first user has the correct name', async () => {
      expect(response.body[0].name).toBe('Alice');
    });

    test('second user has the correct name', async () => {
      expect(response.body[1].name).toBe('Bob');
    });

    test('first user has the correct email', async () => {
      expect(response.body[0].email).toBe('alice@example.com');
    });

    test('second user has the correct email', async () => {
      expect(response.body[1].email).toBe('bob@example.com');
    });

    test('users are returned in ascending id order', async () => {
      const ids = response.body.map((u) => u.id);
      const sorted = [...ids].sort((a, b) => a - b);
      expect(ids).toEqual(sorted);
    });

    test('every user has a unique id', async () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('every user has a unique email address', async () => {
      const emails = response.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });
  });

  // -------------------------------------------------------------------------
  // Schema / response-format tests
  // -------------------------------------------------------------------------
  describe('Response schema validation', () => {
    let body;

    beforeEach(async () => {
      const res = await request(server).get('/users');
      body = res.body;
    });

    test('each user contains exactly the keys: id, name, email', async () => {
      body.forEach((user) => {
        const keys = Object.keys(user).sort();
        expect(keys).toEqual(['email', 'id', 'name']);
      });
