/**
 * Test suite for the /users endpoint in app.js
 *
 * Dependencies:
 *   npm install --save-dev jest supertest
 *
 * Run with:
 *   npx jest app.test.js
 *   npx jest --coverage app.test.js   (to include coverage report)
 */

const request = require('supertest');
const app = require('./app');

// ---------------------------------------------------------------------------
// Schema validation helper
// ---------------------------------------------------------------------------

/**
 * Validates that a single user object conforms to the expected schema.
 *
 * Expected shape:
 *   {
 *     id:    number  – positive integer, unique identifier
 *     name:  string  – non-empty display name
 *     email: string  – valid e-mail address
 *   }
 */
function validateUserSchema(user) {
  // --- id ---
  expect(user).toHaveProperty('id');
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // --- name ---
  expect(user).toHaveProperty('name');
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // --- email ---
  expect(user).toHaveProperty('email');
  expect(typeof user.email).toBe('string');
  // RFC-5322-lite: something@something.something
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  // --- no extra undocumented fields ---
  const allowedKeys = ['id', 'name', 'email'];
  const extraKeys = Object.keys(user).filter((k) => !allowedKeys.includes(k));
  expect(extraKeys).toHaveLength(0);
}

// ---------------------------------------------------------------------------
// Shared server lifecycle
// ---------------------------------------------------------------------------

let server;

beforeAll((done) => {
  // Bind to port 0 so the OS picks a free port – avoids collisions in CI.
  server = app.listen(0, done);
});

afterAll((done) => {
  server.close(done);
});

// ---------------------------------------------------------------------------
// 1. Happy-path tests
// ---------------------------------------------------------------------------

describe('GET /users – happy path', () => {
  test('responds with HTTP 200', async () => {
    const res = await request(server).get('/users');

    expect(res.status).toBe(200);
  });

  test('responds with Content-Type: application/json', async () => {
    const res = await request(server).get('/users');

    expect(res.headers['content-type']).toMatch(/application\/json/);
  });

  test('returns an array', async () => {
    const res = await request(server).get('/users');

    expect(Array.isArray(res.body)).toBe(true);
  });

  test('returns a non-empty list of users', async () => {
    const res = await request(server).get('/users');

    expect(res.body.length).toBeGreaterThan(0);
  });

  test('returns exactly 2 users', async () => {
    const res = await request(server).get('/users');

    expect(res.body).toHaveLength(2);
  });

  test('first user has the correct values', async () => {
    const res = await request(server).get('/users');
    const [alice] = res.body;

    expect(alice.id).toBe(1);
    expect(alice.name).toBe('Alice');
    expect(alice.email).toBe('alice@example.com');
  });

  test('second user has the correct values', async () => {
    const res = await request(server).get('/users');
    const [, bob] = res.body;

    expect(bob.id).toBe(2);
    expect(bob.name).toBe('Bob');
    expect(bob.email).toBe('bob@example.com');
  });

  test('every user id is unique', async () => {
    const res = await request(server).get('/users');
    const ids = res.body.map((u) => u.id);
    const uniqueIds = new Set(ids);

    expect(uniqueIds.size).toBe(ids.length);
  });

  test('returns the same data on repeated calls (deterministic)', async () => {
    const [res1, res2] = await Promise.all([
      request(server).get('/users'),
      request(server).get('/users'),
    ]);

    expect(res1.body).toEqual(res2.body);
  });
});

// ---------------------------------------------------------------------------
// 2. Schema-validation tests
// ---------------------------------------------------------------------------

describe('GET /users – response schema', () => {
  test('response body is a JSON array (not an object or primitive)', async () => {
    const res = await request(server).get('/users');

    expect(res.body).not.toBeNull();
    expect(typeof res.body).not.toBe('string');
    expect(typeof res.body).not.toBe('number');
    expect(Array.isArray(res.body)).toBe(true);
  });

  test('every user object conforms to the expected schema', async () => {
    const res = await request(server).get('/users');

    res.body.forEach((user, index) => {
      try {
        validateUserSchema(user);
      } catch (err) {
        // Surface which user index failed for easier debugging.
        throw new Error(`Schema violation at users[${index}]: ${err.message}`);
      }
    });
  });

  test('user ids are positive integers', async () => {
    const res = await request(server).get('/users');

    res.body.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('user names are non-empty strings', async () => {
    const res = await request(server).get('/users');

    res.body.forEach((user) => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim()).not.toBe('');
    });
  });

  test('user emails are valid email addresses', async () => {
    const res = await request(server).get('/users');

    res.body.forEach((user) => {
      expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
    });
  });

  test('user objects contain no unexpected extra fields', async () => {
    const res = await request(server).get('/users');
    const allowedKeys = ['id', 'name', 'email'];

    res.body.forEach((user, index) => {
      const extraKeys = Object.keys(user).filter((k) => !allowedKeys.includes(k));
      expect(extraKeys).toHaveLength(0);
      if (extraKeys.length > 0) {
        throw new Error(
          `users[${index}] contains unexpected field(s): ${extraKeys.join(', ')}`
        );
      }
    });
  });

  test('response matches the full expected snapshot', async () => {
    const res = await request(server).get('/users');

    expect(res.body).toEqual([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  });
});

// ---------------------------------------------------------------------------
// 3. Error-handling tests
// ---------------------------------------------------------------------------

describe('GET /users – error handling and edge cases', () => {
  test('returns 404 for a non-existent route', async () => {
    const res = await request(server).get('/users/999');

    expect(res.status).toBe(404);
  });

  test('does not accept POST on /users (405 or 404)', async () => {
    const res = await request(server).post('/users').send({ name: 'Eve' });

    // Express returns 404 for unregistered method+path combos by default.
    // If the app later adds explicit 405 handling, both statuses are valid.
    expect([404, 405]).toContain(res.status);
  });

