/**
 * app.test.js
 *
 * Unit / integration tests for the /users endpoint in app.js.
 *
 * Test runner : Jest  (https://jestjs.io)
 * HTTP helper : Supertest  (https://github.com/ladjs/supertest)
 *
 * Run:
 *   npx jest            # or: npm test
 *   npx jest --verbose  # human-readable per-test output
 *   npx jest --coverage # with code-coverage report
 */

const request = require('supertest');
const app     = require('./app');

// ---------------------------------------------------------------------------
// Helper – tiny JSON-schema–style validator used in the schema-contract suite.
// Keeps the tests self-contained without pulling in ajv / joi.
// ---------------------------------------------------------------------------

/**
 * Asserts that `value` matches `schema`.
 *
 * Supported schema keys
 *   type       – "string" | "number" | "array" | "object"
 *   required   – array of required property names (objects only)
 *   properties – { key: schema } map (objects only)
 *   items      – schema applied to every array element
 *   minLength  – minimum array or string length
 */
function assertMatchesSchema(value, schema, path = 'root') {
  // ── type check ────────────────────────────────────────────────────────────
  if (schema.type) {
    const actualType = Array.isArray(value) ? 'array' : typeof value;
    expect(`${path}:type=${actualType}`).toBe(`${path}:type=${schema.type}`);
  }

  // ── array rules ───────────────────────────────────────────────────────────
  if (schema.type === 'array') {
    if (schema.minLength !== undefined) {
      expect(value.length).toBeGreaterThanOrEqual(schema.minLength);
    }
    if (schema.items) {
      value.forEach((item, i) =>
        assertMatchesSchema(item, schema.items, `${path}[${i}]`),
      );
    }
  }

  // ── object rules ─────────────────────────────────────────────────────────
  if (schema.type === 'object') {
    if (schema.required) {
      schema.required.forEach(key => {
        expect(
          Object.prototype.hasOwnProperty.call(value, key),
        ).toBe(true); // `${path}.${key}` must be present
      });
    }
    if (schema.properties) {
      Object.entries(schema.properties).forEach(([key, subSchema]) => {
        if (Object.prototype.hasOwnProperty.call(value, key)) {
          assertMatchesSchema(value[key], subSchema, `${path}.${key}`);
        }
      });
    }
  }

  // ── string rules ─────────────────────────────────────────────────────────
  if (schema.type === 'string' && schema.minLength !== undefined) {
    expect(value.length).toBeGreaterThanOrEqual(schema.minLength);
  }
}

// ---------------------------------------------------------------------------
// Expected JSON schema for a single user object
// ---------------------------------------------------------------------------
const USER_SCHEMA = {
  type: 'object',
  required: ['id', 'name', 'email'],
  properties: {
    id:    { type: 'number' },
    name:  { type: 'string', minLength: 1 },
    email: { type: 'string', minLength: 1 },
  },
};

// Expected schema for the full /users response body
const USERS_RESPONSE_SCHEMA = {
  type: 'array',
  minLength: 1,
  items: USER_SCHEMA,
};

// ---------------------------------------------------------------------------
// Test suites
// ---------------------------------------------------------------------------

describe('GET /users', () => {

  // ── Happy-path ─────────────────────────────────────────────────────────
  describe('Happy path', () => {

    test('responds with HTTP 200', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
    });

    test('responds with Content-Type application/json', async () => {
      const res = await request(app).get('/users');
      expect(res.headers['content-type']).toMatch(/application\/json/);
    });

    test('returns an array', async () => {
      const res = await request(app).get('/users');
      expect(Array.isArray(res.body)).toBe(true);
    });

    test('returns at least one user', async () => {
      const res = await request(app).get('/users');
      expect(res.body.length).toBeGreaterThan(0);
    });

    test('returns the seeded users Alice and Bob', async () => {
      const res  = await request(app).get('/users');
      const names = res.body.map(u => u.name);
      expect(names).toContain('Alice');
      expect(names).toContain('Bob');
    });

    test('every user has a unique numeric id', async () => {
      const res = await request(app).get('/users');
      const ids = res.body.map(u => u.id);

      ids.forEach(id => expect(typeof id).toBe('number'));

      const unique = new Set(ids);
      expect(unique.size).toBe(ids.length);
    });

    test('every user has a non-empty name string', async () => {
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('every user has a valid-looking e-mail address', async () => {
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const res      = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.email).toBe('string');
        expect(EMAIL_RE.test(user.email)).toBe(true);
      });
    });

  }); // Happy path

  // ── Schema contract ───────────────────────────────────────────────────
  describe('Response schema contract', () => {

    test('response body matches the USERS_RESPONSE_SCHEMA', async () => {
      const res = await request(app).get('/users');
      // assertMatchesSchema throws (via Jest expect) on the first mismatch
      expect(() =>
        assertMatchesSchema(res.body, USERS_RESPONSE_SCHEMA),
      ).not.toThrow();
    });

    test('each user object contains exactly the expected keys (no extras)', async () => {
      const EXPECTED_KEYS = new Set(['id', 'name', 'email']);
      const res           = await request(app).get('/users');

      res.body.forEach((user, index) => {
        const actual = new Set(Object.keys(user));
        // All required keys present
        EXPECTED_KEYS.forEach(k =>
          expect(actual.has(k)).toBe(true),
        );
        // No unexpected extra keys
        actual.forEach(k =>
          expect(EXPECTED_KEYS.has(k)).toBe(true),
        );
      });
    });

    test('id field is a positive integer', async () => {
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('name field is a non-empty string with no leading/trailing whitespace', async () => {
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.name).toBe('string');
        expect(user.name).toBe(user.name.trim());
        expect(user.name.length).toBeGreaterThan(0);
      });
    });

    test('email field is a non-empty string formatted as an e-mail address', async () => {
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const res      = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.email).toBe('string');
        expect(user.email.length).toBeGreaterThan(0);
        expect(EMAIL_RE.test(user.email)).toBe(true);
      });
    });

  }); // Schema contract

  // ── Error handling ────────────────────────────────────────────────────
  describe('Error handling', () => {

    /**
     * Scenario 1 – The data source throws.
     *
     * We temporarily replace the route handler so we can simulate an
     * unexpected error (e.g. a database failure) without touching app.js.
     * The same technique works for any Express middleware stack.
     */
    describe('when the data source throws an unexpected error', () => {

      let originalHandler;

      beforeEach(() => {
        // Grab the first route that matches GET /users
        const layer = app._router.stack.find(
          l => l.route &&
               l.route.path === '/users' &&
               l.route.methods.get,
        );
        originalHandler = layer.route.stack[0].handle;

        // Replace with a handler that blows up
        layer.route.stack[0].handle = (_req, _res, next) => {
          next(new Error('Simulated data-source failure'));
        };
      });

      afterEach(() => {
        // Restore the original handler so other suites are unaffected
        const layer = app._router.stack.find(
          l => l.route &&
               l.route.path === '/users' &&
               l.route.methods.get,
        );
        layer.route.stack[0].handle = originalHandler;
      });

      test('returns HTTP 500 when an unhandled error is passed to next()', async () => {
        const res = await request(app).get('/users');
        expect(res.statusCode).toBe(500);
      });

    });

    /**
     * Scenario 2 – Wrong HTTP method.
     * Express returns 404 for routes that exist but don't handle the verb.
     */
    test('returns HTTP 404 for POST /users (method not defined)', async () => {
      const res = await request(app).post('/users').send({});
      expect(res.statusCode).toBe(404);
    });

    test('returns HTTP 404 for PUT /users (method not defined)', async () => {
      const res = await request(app).put('/users').send({});
      expect(res.statusCode).toBe(404);
    });

    test('returns HTTP 404 for DELETE /users (method not defined)', async () => {
      const res = await request(app).delete('/users');
      expect(res.statusCode).toBe(404);
    });

    /**
     * Scenario 3 – Nonexistent route.
     */
    test('returns HTTP 404 for a completely unknown route', async () => {
      const res = await request(app).get('/nonexistent');
      expect(res.statusCode).toBe(404);
    });

    /**
     * Scenario 4 – Sub-path that is not registered.
     * /users/:id is not implemented, so it should return 404.
     */
    test('returns HTTP 404 for GET /users/:id (not implemented)', async () => {
      const res = await request(app).get('/users/1');
      expect(res.statusCode).toBe(404);
    });

  }); // Error handling

  // ── Response-body immutability across calls ───────────────────────────
  describe('Consistency across repeated calls', () => {

    test('returns the same data on two consecutive requests', async () => {
      const [res1, res2] = await Promise.all([
        request(app).get('/users'),
        request(app).get('/users'),
      ]);
      expect(res1.body).toEqual(res2.body);
    });

    test('returns an independent copy per request (no shared-state mutation)', async () => {
      const res = await request(app).get('/users');
      const snapshot = JSON.parse(JSON.stringify(res.body)); // deep clone

      // Mutate the local copy
      res.body[0].name = 'MUTATED';

      // A fresh request should still return the original data
      const res2 = await request(app).get('/users');
      expect(res2.body[0].name).toBe(snapshot[0].name);
    });

  }); // Consistency

}); // GET /users

