// Keeps the tests self-contained without pulling in ajv / joi.
// ---------------------------------------------------------------------------

/**
 * Asserts that `value` matches `schema`.
 *
 * Supported schema keys
 *   type       – "string" | "number" | "array" | "object"
 *   required   – array of required property names (objects only)
 *   properties – { key: schema } map (objects only)
 *   items      – schema applied to every array element
 *   minLength  – minimum array or string length
 */
function assertMatchesSchema(value, schema, path = 'root') {
  // ── type check ────────────────────────────────────────────────────────────
  if (schema.type) {
    const actualType = Array.isArray(value) ? 'array' : typeof value;
    expect(`${path}:type=${actualType}`).toBe(`${path}:type=${schema.type}`);
  }

  // ── array rules ───────────────────────────────────────────────────────────
  if (schema.type === 'array') {
    if (schema.minLength !== undefined) {
      expect(value.length).toBeGreaterThanOrEqual(schema.minLength);
    }
    if (schema.items) {
      value.forEach((item, i) =>
        assertMatchesSchema(item, schema.items, `${path}[${i}]`),
      );
    }
  }

  // ── object rules ─────────────────────────────────────────────────────────
  if (schema.type === 'object') {
    if (schema.required) {
      schema.required.forEach(key => {
        expect(
          Object.prototype.hasOwnProperty.call(value, key),
        ).toBe(true); // `${path}.${key}` must be present
      });
    }
    if (schema.properties) {
      Object.entries(schema.properties).forEach(([key, subSchema]) => {
        if (Object.prototype.hasOwnProperty.call(value, key)) {
          assertMatchesSchema(value[key], subSchema, `${path}.${key}`);
        }
      });
    }
  }

  // ── string rules ─────────────────────────────────────────────────────────
  if (schema.type === 'string' && schema.minLength !== undefined) {
    expect(value.length).toBeGreaterThanOrEqual(schema.minLength);
  }
}

