/**
 * Test suite for app.js — /users endpoint
 *
 * Dependencies: jest, supertest
 * Run with:  npm test
 */

const request = require('supertest');
const app = require('./app');

// ---------------------------------------------------------------------------
// Schema validator helper
// Checks that every element of an array matches the expected User shape.
// ---------------------------------------------------------------------------
function isValidUser(obj) {
  return (
    obj !== null &&
    typeof obj === 'object' &&
    typeof obj.id === 'number' &&
    Number.isInteger(obj.id) &&
    obj.id > 0 &&
    typeof obj.name === 'string' &&
    obj.name.trim().length > 0 &&
    typeof obj.email === 'string' &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(obj.email) // basic RFC-like e-mail check
  );
}

// ---------------------------------------------------------------------------
// Shared server lifecycle — avoids "port already in use" between test files
// ---------------------------------------------------------------------------
let server;

beforeAll((done) => {
  // Use a random ephemeral port so tests never collide with a running server
  server = app.listen(0, done);
});

afterAll((done) => {
  server.close(done);
});

// ===========================================================================
// GET /users
// ===========================================================================
describe('GET /users', () => {
  // -------------------------------------------------------------------------
  // Happy-path tests
  // -------------------------------------------------------------------------
  describe('Happy path', () => {
    let response;

    beforeAll(async () => {
      response = await request(server).get('/users');
    });

    test('responds with HTTP 200 OK', () => {
      expect(response.statusCode).toBe(200);
    });

    test('responds with Content-Type: application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('returns an array in the response body', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('returns at least one user', () => {
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('returns the expected number of seeded users (2)', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has the correct name "Alice"', () => {
      expect(response.body[0].name).toBe('Alice');
    });

    test('second user has the correct name "Bob"', () => {
      expect(response.body[1].name).toBe('Bob');
    });

    test('user IDs are unique across the list', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('user IDs are sequential starting from 1', () => {
      const ids = response.body.map((u) => u.id);
      ids.forEach((id, index) => expect(id).toBe(index + 1));
    });

    test('email addresses are unique across the list', () => {
      const emails = response.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });
  });

  // -------------------------------------------------------------------------
  // Response-schema tests
  // -------------------------------------------------------------------------
  describe('Response schema validation', () => {
    let response;

    beforeAll(async () => {
      response = await request(server).get('/users');
    });

    test('every user object has exactly the keys: id, name, email', () => {
      const EXPECTED_KEYS = ['id', 'name', 'email'].sort();
      response.body.forEach((user) => {
        expect(Object.keys(user).sort()).toEqual(EXPECTED_KEYS);
      });
    });

    test('id is a positive integer on every user', () => {
      response.body.forEach((user) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('name is a non-empty string on every user', () => {
      response.body.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('email is a valid e-mail address string on every user', () => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      response.body.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(emailRegex.test(user.email)).toBe(true);
      });
    });

    test('full schema check — all users pass the isValidUser validator', () => {
      response.body.forEach((user) => {
        expect(isValidUser(user)).toBe(true);
      });
    });

    test('response matches the complete expected snapshot', () => {
      expect(response.body).toEqual([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob',   email: 'bob@example.com'   },
      ]);
    });
  });

  // -------------------------------------------------------------------------
  // Error-handling tests
  // -------------------------------------------------------------------------
  describe('Error handling', () => {
    test('returns 404 for a non-existent route', async () => {
      const res = await request(server).get('/users/does-not-exist');
      expect(res.statusCode).toBe(404);
    });

    test('POST /users returns 404 (method not implemented)', async () => {
      const res = await request(server)
        .post('/users')
        .send({ name: 'Charlie', email: 'charlie@example.com' });
      expect(res.statusCode).toBe(404);
    });

    test('PUT /users returns 404 (method not implemented)', async () => {
      const res = await request(server).put('/users');
      expect(res.statusCode).toBe(404);
    });

    test('DELETE /users returns 404 (method not implemented)', async () => {
      const res = await request(server).delete('/users');
      expect(res.statusCode).toBe(404);
    });

    test('PATCH /users returns 404 (method not implemented)', async () => {
      const res = await request(server).patch('/users');
      expect(res.statusCode).toBe(404);
    });

    test('unsupported Accept header still returns JSON (content negotiation)', async () => {
      const res = await request(server)
        .get('/users')
        .set('Accept', 'text/plain');
      // Express ignores unknown Accept types by default and serves JSON anyway
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
    });

    test('handles extra query parameters without error', async () => {
      const res = await request(server).get('/users?foo=bar&limit=10');
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
    });

    test('handles encoded path segments gracefully', async () => {
      const res = await request(server).get('/users/%20');
      expect(res.statusCode).toBe(404);
    });
  });

  // -------------------------------------------------------------------------
  // Resilience / concurrent-request tests
  // -------------------------------------------------------------------------
  describe('Resilience', () => {
    test('handles multiple concurrent requests and returns consistent data', async () => {
      const NUM_REQUESTS = 20;
      const responses = await Promise.all(
        Array.from({ length: NUM_REQUESTS }, () =>
          request(server).get('/users')
        )
      );

      responses.forEach((res) => {
        expect(res.statusCode).toBe(200);
        expect(res.body).toHaveLength(2);
        expect(res.body[0].name).toBe('Alice');
        expect(res.body[1].name).toBe('Bob');
      });
    });

    test('returns identical payloads on repeated sequential requests', async () => {
      const first  = await request(server).get('/users');
      const second = await request(server).get('/users');
      expect(second.body).toEqual(first.body);
    });
  });
});

// ===========================================================================
// GET /health  (sanity-check that the server itself is running correctly)
// ===========================================================================
describe('GET /health', () => {
  test('responds with HTTP 200', async () => {
    const res = await request(server).get('/health');
    expect(res.statusCode).toBe(200);
  });

  test('response body contains status "ok"', async () => {
    const res = await request(server).get('/health');
    expect(res.body.status).toBe('ok');
  });

  test('response body contains a timestamp string', async () => {
    const res = await request(server).get('/health');
    expect(typeof res.body.timestamp).toBe('string');
    expect(isNaN(Date.parse(res.body.timestamp))).toBe(false);
  });
});

